function renderMilestones(colId, data, trackClass) {
  const col = document.getElementById(colId);
  const colHeight = GRID_HEIGHT;
  const CARD_HEIGHT = 38; // approximate card height to detect overlap

  // Sort by date
  const sorted = [...data].sort((a, b) => a.date.localeCompare(b.date));
  let prevBottom = -99;

  sorted.forEach((item, i) => {
    let top = yearToPx(item.date);

    // Avoid overlap: push down if needed
    if (top < prevBottom + 4) {
      top = prevBottom + 4;
    }

    const ms = document.createElement('div');
    ms.className = 'milestone';
    ms.style.top = top + 'px';

    const isCritical = item.significance === 'critical';
    const inner = document.createElement('div');
    inner.className = `milestone-inner ${trackClass}`;
    if (isCritical) inner.style.background = '#fffaf8';

    const dot = document.createElement('div');
    dot.className = `milestone-dot ${item.significance}`;
    if (item.significance === 'critical') { dot.style.width = '10px'; dot.style.height = '10px'; }

    const textDiv = document.createElement('div');
    textDiv.className = 'milestone-text';

    const labelDiv = document.createElement('div');
    labelDiv.className = 'milestone-label';
    labelDiv.textContent = item.label;

    const dateDiv = document.createElement('div');
    dateDiv.className = 'milestone-date';
    dateDiv.textContent = item.date;

    textDiv.appendChild(labelDiv);
    textDiv.appendChild(dateDiv);

    inner.appendChild(dot);
    inner.appendChild(textDiv);

    if (isCritical) {
      const badge = document.createElement('div');
      badge.className = 'badge-critical';
      badge.textContent = 'KEY';
      inner.appendChild(badge);
    }

    ms.appendChild(inner);
    col.appendChild(ms);

    prevBottom = top + CARD_HEIGHT;
  });
}

